 OR NOT(BINARY t.content_sha256<=>BINARY s.content_sha256)
 OR t.previous_sha256 IS NOT NULL
 OR t.event_sha256 IS NOT NULL
 OR NOT(t.quantity<=>s.byte_size)
 OR NOT(BINARY t.unit<=>BINARY IF(s.byte_size IS NULL,NULL,'BYTES'))
 OR t.request_scope IS NOT NULL
 OR t.policy_version IS NOT NULL
 OR NOT(BINARY t.outcome<=>BINARY s.state)
 OR t.observed_at IS NOT NULL
 OR t.observation_model_id IS NOT NULL
 OR t.observation_request_id IS NOT NULL
 OR t.operation_scope IS NOT NULL
 OR t.operation_domain IS NOT NULL
 OR t.operation_result IS NOT NULL
 OR t.legacy_model_attempt_id IS NOT NULL
 OR t.legacy_attempt_model_id IS NOT NULL
 OR NOT(t.occurred_at<=>CONVERT_TZ(s.created_at,'__SOURCE_MODEL_FILE_OFFSET__','+00:00'))
 OR NOT(t.payload_version<=>1)
 OR NOT(BINARY t.payload_json<=>BINARY JSON_OBJECT('retentionId',s.retention_id,'fileId',s.file_id,'storagePath',s.storage_path,'pathSha256',s.path_sha256,'updatedAtUtc',DATE_FORMAT(CONVERT_TZ(s.updated_at,'__SOURCE_MODEL_FILE_OFFSET__','+00:00'),'%Y-%m-%dT%H:%i:%s.%f'),'legacyCreatedAt',DATE_FORMAT(s.created_at,'%Y-%m-%dT%H:%i:%s.%f'),'legacyUpdatedAt',DATE_FORMAT(s.updated_at,'%Y-%m-%dT%H:%i:%s.%f')))
 OR NOT(BINARY t.legacy_source<=>BINARY 'detection_model_file_retention')
 OR NOT(BINARY t.legacy_key<=>BINARY s.retention_id)
 OR t.call_id IS NOT NULL
 OR t.identity_task_id IS NOT NULL
 OR t.identity_role IS NOT NULL
 OR t.identity_source_id IS NOT NULL
 OR t.identity_parent_id IS NOT NULL
 OR t.identity_child_parent_id IS NOT NULL
 OR t.identity_actor_key IS NOT NULL
 OR t.identity_assignment_request_id IS NOT NULL
 OR t.digest_legacy_detail_json IS NOT NULL),1,0);
COMMIT;
